! **************************************************************************************************
!> \brief Routines to calculate the minimax coefficients for approximating tanh(x/2)/x+(1-tanh(x/2)^2)/2 as
!>        tanh(x/2)/x+(1-tanh(x/2)^2)/2 ~ SUM_{i}^{K} w_i x^2/(x^2+a_i^2)^2*tanh(x/2)  for x belonging to [0:Rc].
!> \par History
!>      07.2025 created [Frederick Stein]
! **************************************************************************************************
MODULE minimax_ftrpa
   USE kinds,                           ONLY: dp
#include "../base/base_uses.f90"

   IMPLICIT NONE

   PRIVATE

   CHARACTER(len=*), PARAMETER, PRIVATE :: moduleN = 'minimax_rpa'

   PUBLIC get_ftrpa_minimax_coeff

CONTAINS

! **************************************************************************************************
!> \brief The a_i and w_i coefficient are stored in aw such that the first 1:K
!>        elements correspond to a_i and the K+1:2k correspond to w_i.
!>        All a_i and w_i have been fitted with a 12th order polynomial as
!>        a function of Rc for each value of K.
!> \param k ...
!> \param E_range ...
!> \param aw ...
!> \param ierr ...
!> \param print_warning ...
!> \author Frederick Stein
! **************************************************************************************************
   SUBROUTINE get_ftrpa_minimax_coeff(k, E_range, aw, ierr, print_warning)
      INTEGER                                            :: k
      REAL(KIND=dp)                                      :: E_range
      REAL(KIND=dp), DIMENSION(2*k)                      :: aw
      INTEGER                                            :: ierr
      LOGICAL, OPTIONAL                                  :: print_warning

      CHARACTER(LEN=*), PARAMETER :: routineN = 'get_ftrpa_minimax_coeff'

      CHARACTER(LEN=512)                                 :: error_msg
      CHARACTER(LEN=64)                                  :: Rc_cha
      INTEGER                                            :: handle, icoef, kkk
      LOGICAL                                            :: my_print_warning
      REAL(KIND=dp)                                      :: Lb, R_transf, Rc, Ub
      REAL(KIND=dp), DIMENSION(13, 2*k-1)                  :: fit_data

      CALL timeset(routineN, handle)
      Rc = E_range
      fit_data = 0.0_dp
      ierr = 0

      my_print_warning = .TRUE.
      IF (PRESENT(print_warning)) my_print_warning = print_warning

      SELECT CASE (k)
      CASE (1)
         CALL get_fit_coef_k01(Rc, Lb, Ub, fit_data)
      CASE (2)
         CALL get_fit_coef_k02(Rc, Lb, Ub, fit_data)
      CASE (3)
         CALL get_fit_coef_k03(Rc, Lb, Ub, fit_data)
      CASE (4)
         CALL get_fit_coef_k04(Rc, Lb, Ub, fit_data)
      CASE (5)
         CALL get_fit_coef_k05(Rc, Lb, Ub, fit_data)
      CASE (6)
         CALL get_fit_coef_k06(Rc, Lb, Ub, fit_data)
      CASE (7)
         CALL get_fit_coef_k07(Rc, Lb, Ub, fit_data)
      CASE (8)
         CALL get_fit_coef_k08(Rc, Lb, Ub, fit_data)
      CASE (9)
         CALL get_fit_coef_k09(Rc, Lb, Ub, fit_data)
      CASE (10)
         CALL get_fit_coef_k10(Rc, Lb, Ub, fit_data)
      CASE (11)
         CALL get_fit_coef_k11(Rc, Lb, Ub, fit_data)
      CASE (12)
         CALL get_fit_coef_k12(Rc, Lb, Ub, fit_data)
      CASE (13)
         CALL get_fit_coef_k13(Rc, Lb, Ub, fit_data)
      CASE (14)
         CALL get_fit_coef_k14(Rc, Lb, Ub, fit_data)
      CASE (15)
         CALL get_fit_coef_k15(Rc, Lb, Ub, fit_data)
      CASE (16)
         CALL get_fit_coef_k16(Rc, Lb, Ub, fit_data)
      CASE (17)
         CALL get_fit_coef_k17(Rc, Lb, Ub, fit_data)
      CASE (18)
         CALL get_fit_coef_k18(Rc, Lb, Ub, fit_data)
      CASE (19)
         CALL get_fit_coef_k19(Rc, Lb, Ub, fit_data)
      CASE (20)
         CALL get_fit_coef_k20(Rc, Lb, Ub, fit_data)
      CASE DEFAULT
         k = 20
         CALL get_fit_coef_k20(Rc, Lb, Ub, fit_data(1:13, 1:40))
         ierr = -1
      END SELECT

      IF (my_print_warning) THEN
         Rc_cha = ADJUSTL(Rc_cha)

         IF (E_range < Lb) THEN
            WRITE (error_msg, '(A,A)') " The range for the Minimax approximation is smaller than the lower bound "// &
               "for the required number of quadrature points. The Minimax parameters "// &
               "have been optimized for the lower bound of: ", TRIM(Rc_cha)
            CPWARN(error_msg)
         END IF
         IF (E_range > Rc) THEN
            WRITE (error_msg, '(A,A)') " The range for the Minimax approximation exceeds the upper bound "// &
               "for the required number of quadrature points. The Minimax parameters "// &
               "have been optimized for the upper bound of: ", TRIM(Rc_cha)
            CPWARN(error_msg)
         END IF
         IF (ierr < 0) THEN
            error_msg = "The required number of quadrature point exceeds the maximum available. "// &
                        "The number of quadrature point has been reset to 20."
            CPWARN(error_msg)
         END IF
      END IF

      ! Recalculate the parameters
      R_transf = SQRT(Lb/Rc)
      R_transf = SQRT(R_transf)*(SQRT(Ub/(Ub - Lb)) - SQRT(Rc/(Ub - Lb)))
      DO kkk = 1, 2*k-1
         aw(kkk) = fit_data(1, kkk)
         DO icoef = 2, 13
            aw(kkk) = aw(1+kkk)*R_transf + fit_data(icoef, kkk)
         END DO
      END DO
      ! Transform them back
      ! The first element is the weight of the frequency zero which was shifted by one for optimization
      aw(1) = aw(1) + 1.0_dp
      ! The second half consists of the abscissa with the first abscissa not stored separately (it is always zero)
      ! requiring us to shift them manually
      aw(k+2:2*k) = aw(k+1:2*k-1)
      ! and set the first frequency to zero
      aw(k+1) = 0.0_dp

      CALL timestop(handle)

   END SUBROUTINE get_ftrpa_minimax_coeff

