!> \param Lb ...
!> \param Ub ...
!> \param fit_data ...
! **************************************************************************************************
   SUBROUTINE get_fit_coef_k01(Rc, Lb, Ub, fit_data)
      REAL(KIND=dp)                                      :: Rc, Lb, Ub
      REAL(KIND=dp), DIMENSION(13, 1)                    :: fit_data

      REAL(KIND=dp), DIMENSION(26), PARAMETER :: c01 = [ &
0.3742549366225518_dp, -1.798203619691809_dp, 2.154758508161636_dp, &
-0.537589556646065_dp, 0.01328752332027477_dp, -0.5386337748587179_dp, &
0.02585957460056154_dp, 0.3065121695706834_dp, 0.1468227795071283_dp, &
-0.1047769892202097_dp, -0.1336007449722972_dp, -4.088592595831937e-10_dp, &
