-0.07249907060284627_dp, 0.2380100723011939_dp, -0.006920426559733012_dp, &
-0.09386508256986015_dp, 0.03564784372753586_dp]
REAL(KIND=dp), DIMENSION(13, 1, 2), PARAMETER :: coef_data = RESHAPE(c01, [13, 1, 2])

IF (Rc <= 8.158813320531216_dp) THEN
Rc = 8.158813320531216_dp
END IF
IF (Rc >= 2.0_dp) THEN
Rc = 2.0_dp
END IF
IF (Rc >= 3.996233037643638_dp .AND. Rc <= 8.158813320531216_dp) THEN
! Relative Error: 1.876284160250476e-11
fit_data = coef_data(:, :, 1)
Lb = 3.996233037643638_dp
Ub = 8.158813320531216_dp
END IF
IF (Rc >= 2.0_dp .AND. Rc <= 3.996233037643638_dp) THEN
! Relative Error: 6.614035954800298e-11
fit_data = coef_data(:, :, 2)
Lb = 2.0_dp
Ub = 3.996233037643638_dp
END IF

   END SUBROUTINE get_fit_coef_k01

